def getTime():
    """
    获取小时和分钟
    :return:
    """
    # 获取当前时间
    current_time = datetime.datetime.now()

    # 获取当前小时和分钟
    current_hour = current_time.hour
    current_minute = current_time.minute

    return str(current_hour) + "" + str(current_minute)


def zipOutFile(mem, sourceType):
    """
    在目录下把生成的mapping和dex,放到一起
    :return:
    """
    memDir = outFilePath + "\\" + mem
    if not os.path.exists(memDir):
        os.makedirs(memDir)
    # 复制版本推送成功后, 生成的mapping
    if sourceType == "1":
        mappingPath = "D:\zhangjinming\work\git\entrysoandresource\modules\plugins\mem_loader\obsDataX"
    else:
        mappingPath = "D:\zhangjinming\work\git\entrysoandresource\modules\plugins\mem_loader\obsFirebase"

    files = [mappingPath + "\\mapping\\configuration.txt",
             mappingPath + "\\mapping\\mapping.txt",
             mappingPath + "\\mapping\\\seeds.txt",
             mappingPath + "\\mapping\\usage.txt",
             mappingPath + "\\obs_mapping_mem.txt",
             "D:\\zhangjinming\\work\\git\\entrysoandresource\modules\plugins\mem_loader\classes.dex",
             "D:\\zhangjinming\\work\\git\\entrysoandresource\modules\plugins\mem_loader\obs_classes.jar"]

    for path in files:
        if not os.path.exists(path):
            raise Exception("文件不存在:" + path)
        else:
            fileN = path.split("\\")[-1]
            shutil.copy(path, memDir + "\\" + fileN)

    print("版本文件归档成功, 路径:" + memDir)


def build():
    """
    编译并推送版本
    :return:
    """
    os.chdir(projectPath)
    command = "gradlew :modules:butterfly:publishReleasePublicationToMavenRepository"
    result = subprocess.run(command, shell=True)
    print(result)


def replaceJson(is102, sourceType, cdAarVer):
    """

    :return:
    """
    # 根据sourcetype, 区分要替换的json文件名
    if int(is102) == 1:
        if int(sourceType) == 0:
            obsLibStr = aar_depend_list_firebase_102
            obsSoBeanList = []
        else:
            obsLibStr = aar_depend_list_datax_102
            obsSoBeanList = [{
                "className": "xyz.imzyx.a.prlib.NEP",
                "fileName": "NEP.class",
                "soName": "ajpr",
                "obsMethod": True
            }]
    else:
        obsLibStr = aar_depend_list_datax_103
        obsSoBeanList = []

    if int(sourceType) == 0:
        jsonPath = firebaseJsonPath
        dexPath = dexFirebasePath
    else:
        jsonPath = dataxJsonPath
        dexPath = dexDataxPath
    # 替换到json中的aar版本
    newJsonList = []
    fileIn = open(jsonPath)
    fileContent = fileIn.read()
    jsonData = json.loads(str(fileContent))
    newDexPath = dexPath.replace("###", cdAarVer)
    newJsonEt = jsonData[0]
    newJsonEt["downloadUrl"] = newDexPath
    newJsonEt["obsLibStr"] = obsLibStr
    newJsonEt["obsSoBeanList"] = obsSoBeanList
    newJsonList.append(newJsonEt)
    newContent = json.dumps(newJsonList)
    newFile = open(jsonPath, 'w')
    newFile.write(newContent)
    newFile.close()

    print('obsSoBeanList:' + str(obsSoBeanList))

    # print('newContent:' + newContent)
    # 验证参数是否有误,保证json和properties文件版本能对应上
    checkJsonFile = open(jsonPath)
    jsonData2 = checkJsonFile.read()
    if not str(jsonData2).__contains__(newDexPath):
        raise Exception("dex版本与json文件不对应")

    if int(is102) == 1 and int(sourceType) != 0:
        if not str(jsonData2).__contains__("xyz.imzyx.a.prlib.NEP"):
            raise Exception("json文件内容异常,未包含xyz.imzyx.a.prlib.NEP")
    else:
        if str(jsonData2).__contains__("xyz.imzyx.a.prlib.NEP"):
            raise Exception("json文件内容异常,包含xyz.imzyx.a.prlib.NEP")

def replaceAarVersion(sourceType, cdAarVer, singleId, is102):
    """
    替换aar版本
    :return:
    """
    # 根据sourcetype, 区分要替换的json文件名
    replaceJson(is102, sourceType, cdAarVer)

    # 替换gradle.properties文件
    gpFile = open(gradleProperties, "rb+")
    gpLines = gpFile.readlines()
    mem = cdAarVer + "_" + sourceType + "." + singleId + "." + getTime()
    newLines = []
    for line in gpLines:
        line = line.decode()
        name = line.split("=")[0].replace(" ", "").replace("\n", '').replace("\r", '').replace("\"", "")
        if name == "singleid":
            newLine = "singleid=" + singleId + "\n"
        elif name == 'mem_aar_version':
            newLine = "mem_aar_version=" + mem + "\n"
        elif name == 'sourceType':
            newLine = "sourceType=" + sourceType + "\n"
        else:
            newLine = line
        newLines.append(newLine.encode())

    # print(newLines)
    newGpFile = open(gradleProperties, 'wb+')
    newGpFile.writelines(newLines)
    newGpFile.close()
    checkPropertiesFile = open(gradleProperties, "rb+")
    gpData = checkPropertiesFile.read()
    gpData = gpData.decode()
    if not gpData.__contains__("mem_aar_version=" + mem) or not gpData.__contains__("singleid=" + singleId):
        raise Exception("mem版本和gradleProperties内容对应不上")
    print("版本替换完毕....")
    return mem


if __name__ == '__main__':
    # 获取命令行传递的参数
    if len(sys.argv) > 1:
        cdAarVer = sys.argv[1]
        singleId = sys.argv[2]
        sourceType = sys.argv[3]
        is102 = sys.argv[4]
        print(f"传递的参数是: {sys.argv}")
        mem = replaceAarVersion(sourceType, cdAarVer, singleId, is102)
        build()
        print("dex版本生成成功 :" + mem)
        zipOutFile(mem, sourceType)
